SELECT plan_fingerprint FROM model_runtime.platform_capability_verification_reservation
WHERE id = #{r.id} AND status = 'ACTIVE' AND deployment_id = #{r.deployment.id.value} AND deployment_revision = #{r.deployment.version}
  AND target_fingerprint = #{r.targetFingerprint} AND inputs_digest = #{r.inputsDigest} AND plan_fingerprint = #{r.planFingerprint}
  AND quote_digest = #{r.quoteDigest} AND quote_expires_at = #{r.quoteExpiresAt} AND sample_version = #{r.sampleVersion}
  AND actor_subject_id = #{r.actor.subjectId.value} AND actor_permission_version = #{r.actor.permissionVersion}
  AND reserved_fee = #{r.reservedFee} AND started_at = #{r.startedAt} AND deadline = #{r.deadline} FOR UPDATE

mapper.update:
UPDATE model_runtime.platform_model_deployment
SET status = #{d.status}, last_verification_id = #{d.lastVerificationId.value}, verification_expires_at = #{d.verificationExpiresAt}, version = #{d.version}
WHERE id = #{d.id.value} AND scope = 'PLATFORM' AND version = #{expected} AND status = 'DRAFT'

UPDATE model_runtime.platform_capability_verification_reservation
SET status = 'COMPLETED', outcome = #{outcome}, attempted_requests = #{count}, passed_sample_digests = string_to_array(#{passed}, ','), completed_at = #{now}
WHERE id = #{r.id} AND status = 'ACTIVE' AND plan_fingerprint = #{r.planFingerprint}
